List<Entity> near(double x, double y, double r) {
    List<Entity> out = new ArrayList<>();
    for (int cy = cellY(y - r); cy <= cellY(y + r); cy++)
        for (int cx = cellX(x - r); cx <= cellX(x + r); cx++)
            for (Entity e : cells.getOrDefault(key(cx, cy), List.of()))
                if (e.distanceTo(x, y) <= r) out.add(e);
    return out;
}

